const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');const start=document.getElementById('start-btn'),title=document.getElementById('title-card'),hud=document.getElementById('hud'),death=document.getElementById('death'),retry=document.getElementById('retry'),warning=document.getElementById('warning'),batteryFill=document.getElementById('battery-fill'),batteryText=document.getElementById('battery-text'),clock=document.getElementById('clock'),levelToast=document.getElementById('level-toast');
let W,H,dpr,playing=false,dead=false,last=0,elapsed=0,light=true,battery=87,keys={},mouseDown=false;let player={x:2.5,y:2.5,a:0};
const map=["################","#..............#","#.####.#####...#","#.#..#.....#...#","#.#..###.#.###.#","#.#......#.....#","#.###########..#","#..............#","#.######.#####.#","#......#.......#","#.####.#.#####.#","#....#.#.....#.#","#....#.#####.#.#","#............#.#","#..............#","################"];
let bots=[{x:6.5,y:1.8,a:2.4,name:'kestrel',color:'#7196a5',phase:0},{x:13.3,y:7.7,a:3.1,name:'rue_404',color:'#9b6b64',phase:3}];let hound={x:11.5,y:11.5,a:0,active:true};let exit={x:13.4,y:13.5};
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
function wall(x,y){return y<0||y>=map.length||x<0||x>=map[0].length||map[Math.floor(y)][Math.floor(x)]==='#'}function move(x,y){if(!wall(x-.18,y)&&!wall(x+.18,y)&&!wall(x,y-.18)&&!wall(x,y+.18)){player.x=x;player.y=y}}
function cast(angle){let sin=Math.sin(angle),cos=Math.cos(angle),d=0;while(d<24){d+=.035;if(wall(player.x+cos*d,player.y+sin*d))return d}return 24}
function startGame(){playing=true;dead=false;title.classList.add('hidden');death.classList.add('hidden');hud.classList.remove('hidden');canvas.requestPointerLock?.();last=performance.now();requestAnimationFrame(loop)}
start.onclick=startGame;retry.onclick=()=>{player={x:2.5,y:2.5,a:0};battery=87;hound.active=true;startGame()};canvas.onclick=()=>{if(playing)canvas.requestPointerLock?.()};document.addEventListener('pointerlockchange',()=>{});document.addEventListener('mousemove',e=>{if(playing&&!dead&&document.pointerLockElement===canvas)player.a+=e.movementX*.0022});
addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if(e.key.toLowerCase()==='f'){light=!light;if(light&&battery<=0)light=false}if(e.key==='Escape')document.exitPointerLock?.()});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('touchstart',e=>{e.preventDefault();keys[b.dataset.key]=true},{passive:false});b.addEventListener('touchend',()=>keys[b.dataset.key]=false)});document.getElementById('mobile-light').onclick=()=>{light=!light};
function drawWorld(){let horizon=H*.49;ctx.fillStyle='#77705b';ctx.fillRect(0,0,W,horizon);ctx.fillStyle='#433e32';ctx.fillRect(0,horizon,W,H-horizon);let grad=ctx.createLinearGradient(0,horizon,0,H);grad.addColorStop(0,'#38352c');grad.addColorStop(1,'#11110f');ctx.fillStyle=grad;ctx.fillRect(0,horizon,W,H-horizon);let fov=Math.PI/3,step=2;let depths=[];for(let x=0;x<W;x+=step){let ray=player.a-fov/2+fov*x/W,d=cast(ray),correct=d*Math.cos(ray-player.a);depths[x]=correct;let height=Math.min(H*2,H/(correct*.72));let top=horizon-height/2;let shade=Math.max(15,100-correct*4);let warm=light?Math.max(0,1-correct/9):Math.max(0,1-correct/4);ctx.fillStyle=`rgb(${shade+warm*45},${shade+warm*39},${shade+warm*18})`;ctx.fillRect(x,top,step+1,height);if(correct<5&&x%16===0){ctx.fillStyle=`rgba(212,188,119,${light?.08:0})`;ctx.fillRect(x,top,1,height)}}return {fov,depths,horizon}}
function sprite(o,kind,world){let dx=o.x-player.x,dy=o.y-player.y,dist=Math.hypot(dx,dy),ang=Math.atan2(dy,dx)-player.a;while(ang>Math.PI)ang-=Math.PI*2;while(ang<-Math.PI)ang+=Math.PI*2;if(Math.abs(ang)>world.fov*.65)return;let sx=W/2+Math.tan(ang)/Math.tan(world.fov/2)*W/2;let size=Math.min(H*1.3,H/(dist*.75));let z=world.horizon-size*.5;if(world.depths[Math.max(0,Math.min(W-1,Math.floor(sx)))]<dist*.92)return;ctx.save();ctx.globalAlpha=Math.max(.15,1-dist/14);if(kind==='bot'){ctx.fillStyle=o.color;ctx.beginPath();ctx.arc(sx,z+size*.36,size*.12,0,7);ctx.fill();ctx.fillRect(sx-size*.11,z+size*.46,size*.22,size*.4);ctx.fillStyle='#d5ad59';ctx.fillRect(sx-size*.1,z+size*.51,2,2)}else if(kind==='hound'){ctx.fillStyle='#0c0b09';ctx.beginPath();ctx.ellipse(sx,z+size*.52,size*.2,size*.32,0,0,7);ctx.fill();ctx.fillStyle='#ba3029';ctx.shadowBlur=14;ctx.shadowColor='#d33229';ctx.fillRect(sx-size*.1,z+size*.45,4,3);ctx.fillRect(sx+size*.06,z+size*.45,4,3);ctx.shadowBlur=0}else{ctx.fillStyle='#b9a159';ctx.shadowBlur=25;ctx.shadowColor='#e1bb57';ctx.beginPath();ctx.arc(sx,z+size*.4,size*.1,0,7);ctx.fill();ctx.shadowBlur=0}ctx.restore()}
function update(dt){let speed=2.1*dt*(keys.shift?1.45:1),nx=player.x,ny=player.y;if(keys.w||keys.arrowup){nx+=Math.cos(player.a)*speed;ny+=Math.sin(player.a)*speed}if(keys.s||keys.arrowdown){nx-=Math.cos(player.a)*speed;ny-=Math.sin(player.a)*speed}if(keys.a){nx+=Math.cos(player.a-Math.PI/2)*speed;ny+=Math.sin(player.a-Math.PI/2)*speed}if(keys.d){nx+=Math.cos(player.a+Math.PI/2)*speed;ny+=Math.sin(player.a+Math.PI/2)*speed}if(!wall(nx,player.y))player.x=nx;if(!wall(player.x,ny))player.y=ny;if(light){battery-=dt*1.25;if(battery<=0){battery=0;light=false}}else battery=Math.min(100,battery+dt*.08);bots.forEach((b,i)=>{b.phase+=dt;let tx=Math.sin(b.phase*.35+i)*.15,ty=Math.cos(b.phase*.3+i)*.1;if(!wall(b.x+tx,b.y))b.x+=tx*dt;if(!wall(b.x,b.y+ty))b.y+=ty*dt;b.a+=dt*.15});if(hound.active){let dx=player.x-hound.x,dy=player.y-hound.y,dist=Math.hypot(dx,dy);if(dist<7){hound.x+=dx/dist*dt*.3;hound.y+=dy/dist*dt*.3;hound.a=Math.atan2(dy,dx);warning.classList.add('show')}else warning.classList.remove('show');if(dist<.65){dead=true;death.classList.remove('hidden');hud.classList.add('hidden');document.exitPointerLock?.()}}if(Math.hypot(player.x-exit.x,player.y-exit.y)<.8){hound.active=false;levelToast.classList.remove('hidden');setTimeout(()=>levelToast.classList.add('hidden'),4000);document.getElementById('level-name').textContent='THE HUB';document.querySelector('.level-tag').textContent='LEVEL 1';document.getElementById('objective').textContent='Find the red door';exit={x:13.4,y:2.2}}if(!hound.active&&Math.hypot(player.x-exit.x,player.y-exit.y)<.8){player.x=2.5;player.y=2.5;hound.active=true;document.getElementById('level-name').textContent='HABITATION';document.querySelector('.level-tag').textContent='LEVEL 0';document.getElementById('objective').textContent='Locate an exit'}}
function render(){ctx.clearRect(0,0,W,H);let world=drawWorld();[...bots.map(x=>[x,'bot']),...(hound.active?[[hound,'hound']]:[]),[exit,'exit']].sort((a,b)=>Math.hypot(b[0].x-player.x,b[0].y-player.y)-Math.hypot(a[0].x-player.x,a[0].y-player.y)).forEach(x=>sprite(x[0],x[1],world));if(!light){ctx.fillStyle='rgba(0,0,0,.62)';ctx.fillRect(0,0,W,H);let g=ctx.createRadialGradient(W/2,H*.49,15,W/2,H*.49,180);g.addColorStop(0,'rgba(40,38,28,.2)');g.addColorStop(1,'rgba(0,0,0,.7)');ctx.fillStyle=g;ctx.fillRect(0,0,W,H)}batteryFill.style.width=battery+'%';batteryText.textContent=Math.floor(battery)+'%';clock.textContent=Math.floor(elapsed/60).toString().padStart(2,'0')+':'+Math.floor(elapsed%60).toString().padStart(2,'0')}
function loop(t){if(!playing)return;let dt=Math.min(.05,(t-last)/1000);last=t;if(!dead){elapsed+=dt;update(dt);render()}requestAnimationFrame(loop)}

